function tokenize(expr) {
  const tokens = [];
  const regex = /(\d+(\.\d+)?|[+\-*/()])/g;
  let match;

  while ((match = regex.exec(expr)) !== null) {
    tokens.push(match[0]);
  }

  // Check if there are any remaining characters that aren't valid tokens
  const remaining = expr.replace(regex, '');
  if (remaining.trim() !== '') {
    throw new Error(`Invalid character: ${remaining.trim()[0]}`);
  }

  return tokens;
}

function evaluate(expr) {
  const tokens = tokenize(expr);

  // Convert to postfix notation using Shunting Yard algorithm
  const output = [];
  const operators = [];
  const precedence = { '+': 1, '-': 1, '*': 2, '/': 2 };

  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];

    if (/^\d+(\.\d+)?$/.test(token)) {
      output.push(parseFloat(token));
    } else if (token === '(') {
      operators.push(token);
    } else if (token === ')') {
      while (operators.length > 0 && operators[operators.length - 1] !== '(') {
        output.push(operators.pop());
      }
      if (operators.length === 0) {
        throw new Error('Mismatched parentheses');
      }
      operators.pop(); // Remove '('
    } else if (['+', '-', '*', '/'].includes(token)) {
      while (operators.length > 0 && 
             operators[operators.length - 1] !== '(' &&
             precedence[operators[operators.length - 1]] >= precedence[token]) {
        output.push(operators.pop());
      }
      operators.push(token);
    } else {
      throw new Error(`Invalid token: ${token}`);
    }
  }

  while (operators.length > 0) {
    const op = operators.pop();
    if (op === '(' || op === ')') {
      throw new Error('Mismatched parentheses');
    }
    output.push(op);
  }

  // Evaluate postfix notation
  const stack = [];
  for (let i = 0; i < output.length; i++) {
    const token = output[i];
    if (typeof token === 'number') {
      stack.push(token);
    } else {
      if (stack.length < 2) {
        throw new Error('Invalid expression');
      }
      const b = stack.pop();
      const a = stack.pop();

      switch (token) {
        case '+':
          stack.push(a + b);
          break;
        case '-':
          stack.push(a - b);
          break;
        case '*':
          stack.push(a * b);
          break;
        case '/':
          if (b === 0) {
            throw new Error('Division by zero');
          }
          stack.push(a / b);
          break;
        default:
          throw new Error(`Invalid operator: ${token}`);
      }
    }
  }

  if (stack.length !== 1) {
    throw new Error('Invalid expression');
  }

  return stack[0];
}

module.exports = { tokenize, evaluate };

